using ContentOS.Domain;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.ChangeTracking;
namespace ContentOS.Infrastructure;

public sealed partial class CoreDbContext
{
    public DbSet<WatchTemplate> WatchTemplates => Set<WatchTemplate>(); public DbSet<WatchProfile> WatchProfiles => Set<WatchProfile>(); public DbSet<WatchProduction> WatchProductions => Set<WatchProduction>(); public DbSet<WatchStage> WatchStages => Set<WatchStage>(); public DbSet<WatchArtifact> WatchArtifacts => Set<WatchArtifact>(); public DbSet<WatchOperation> WatchOperations => Set<WatchOperation>();
    private static readonly Type[] WatchTypes = [typeof(WatchTemplate), typeof(WatchProfile), typeof(WatchProduction), typeof(WatchStage), typeof(WatchArtifact), typeof(WatchOperation)];
    private static void ConfigureWatch(ModelBuilder m)
    {
        foreach (var t in WatchTypes) { var e = m.Entity(t); e.ToTable(t.Name, "watch"); e.HasKey("Id"); e.Property("RowVersion").IsRowVersion(); e.HasAlternateKey("Id", "UniverseId", "TenantId"); e.HasOne(typeof(Universe)).WithMany().HasForeignKey("UniverseId", "TenantId").HasPrincipalKey("Id", "TenantId").OnDelete(DeleteBehavior.Restrict); foreach (var p in e.Metadata.GetProperties().Where(x => x.ClrType == typeof(string))) p.SetMaxLength(p.Name.EndsWith("Json") ? -1 : p.Name == "Outcome" ? 1000 : 200); }
        m.Entity<WatchTemplate>().HasIndex(x => new { x.TenantId, x.UniverseId, x.Key, x.Version }).IsUnique(); m.Entity<WatchProfile>().HasIndex(x => new { x.TenantId, x.UniverseId, x.Key, x.Version }).IsUnique(); m.Entity<WatchProduction>().HasIndex(x => new { x.TenantId, x.UniverseId, x.Key, x.Version }).IsUnique();
        m.Entity<WatchProduction>().HasOne<WatchProfile>().WithMany().HasForeignKey(x => new { x.ProfileId, x.UniverseId, x.TenantId }).HasPrincipalKey(x => new { x.Id, x.UniverseId, x.TenantId }).OnDelete(DeleteBehavior.Restrict); m.Entity<WatchProduction>().HasOne<ContentRevision>().WithMany().HasForeignKey(x => x.CoreRevisionId).OnDelete(DeleteBehavior.Restrict);
        m.Entity<WatchStage>().HasOne<WatchProduction>().WithMany().HasForeignKey(x => new { x.ProductionId, x.UniverseId, x.TenantId }).HasPrincipalKey(x => new { x.Id, x.UniverseId, x.TenantId }).OnDelete(DeleteBehavior.Restrict); m.Entity<WatchStage>().HasIndex(x => new { x.ProductionId, x.Sequence }).IsUnique(); m.Entity<WatchStage>().Property(x => x.ActualCost).HasPrecision(18, 4); m.Entity<WatchStage>().HasIndex(x => new { x.State, x.NextUtc, x.LeaseUntilUtc });
        m.Entity<WatchArtifact>().HasOne<WatchProduction>().WithMany().HasForeignKey(x => new { x.ProductionId, x.UniverseId, x.TenantId }).HasPrincipalKey(x => new { x.Id, x.UniverseId, x.TenantId }).OnDelete(DeleteBehavior.Restrict); m.Entity<WatchArtifact>().HasOne<WatchStage>().WithMany().HasForeignKey(x => new { x.StageId, x.UniverseId, x.TenantId }).HasPrincipalKey(x => new { x.Id, x.UniverseId, x.TenantId }).OnDelete(DeleteBehavior.Restrict); m.Entity<WatchArtifact>().HasIndex(x => x.StageId).IsUnique(); m.Entity<WatchArtifact>().HasOne<CoreAssetReference>().WithMany().HasForeignKey(x => x.AssetReferenceId).OnDelete(DeleteBehavior.Restrict); m.Entity<WatchOperation>().HasIndex(x => new { x.TenantId, x.OperationId }).IsUnique();
    }
    private static void ValidateWatchChange(EntityEntry e)
    { if (!WatchTypes.Contains(e.Entity.GetType())) return; if (e.State == EntityState.Deleted) throw new InvalidOperationException("WATCH history cannot be deleted."); if (e.State != EntityState.Modified) return; string[] allowed = e.Entity switch { WatchTemplate => ["ReviewStatus", "ReviewJson"], WatchProfile => ["Enabled"], WatchProduction => ["TimelineJson", "State", "ReviewJson", "ReviewMinutes"], WatchStage => ["State", "Attempts", "LeaseToken", "LeaseUntilUtc", "NextUtc", "OutputJson", "ExternalResourceId", "Outcome", "ActualCost"], _ => [] }; if (e.Properties.Any(p => p.IsModified && p.Metadata.Name != "UpdatedUtc" && !allowed.Contains(p.Metadata.Name))) throw new InvalidOperationException("WATCH immutable snapshot/binding cannot change."); if (e.Entity is WatchProduction && e.Property("TimelineJson").IsModified && e.Property("TimelineJson").OriginalValue != null) throw new InvalidOperationException("Append a corrected production; accepted timeline is frozen."); if (e.Entity is WatchStage && e.Property("OutputJson").IsModified && e.Property("OutputJson").OriginalValue != null && e.Property("State").OriginalValue?.ToString() == "Accepted") throw new InvalidOperationException("Accepted stage output is immutable."); }
}
